import { useState, useEffect } from 'react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import { Building2, MapPin, Users, FileText, AlertTriangle, ArrowLeft, Save, X } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'
import { useNavigate } from 'react-router-dom'

interface Venue {
  id?: string
  name: string
  address?: string
  city?: string
  state?: string
  zip_code?: string
  capacity?: number
  description?: string
  is_active: boolean
  created_at?: string
  updated_at?: string
}

interface VenueFormData {
  name: string
  address: string
  city: string
  state: string
  zip_code: string
  capacity: string
  description: string
  is_active: boolean
}

interface VenueFormProps {
  mode: 'create' | 'edit'
  venue?: Venue
  onSubmit: (venueData: VenueFormData) => Promise<void>
  loading?: boolean
}

interface FormErrors {
  [key: string]: string
}

interface Notification {
  type: 'success' | 'error'
  message: string
}

const containerVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: {
      duration: 0.5,
      staggerChildren: 0.1
    }
  }
} as const

const itemVariants = {
  hidden: { opacity: 0, y: 10 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.3 }
  }
} as const

export default function VenueForm({ mode, venue, onSubmit, loading = false }: VenueFormProps) {
  const navigate = useNavigate()

  const [formData, setFormData] = useState<VenueFormData>({
    name: '',
    address: '',
    city: '',
    state: '',
    zip_code: '',
    capacity: '',
    description: '',
    is_active: true
  })

  const [formErrors, setFormErrors] = useState<FormErrors>({})
  const [notification, setNotification] = useState<Notification | null>(null)

  // Pre-populate form data when editing
  useEffect(() => {
    if (mode === 'edit' && venue) {
      setFormData({
        name: venue.name || '',
        address: venue.address || '',
        city: venue.city || '',
        state: venue.state || '',
        zip_code: venue.zip_code || '',
        capacity: venue.capacity ? venue.capacity.toString() : '',
        description: venue.description || '',
        is_active: venue.is_active
      })
